{"record_type":"obligation_result","obligation_index":0,"status":"items","reason_code":null,"items":[{"text":"我们是西北有色金属研究院，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
