{"record_type":"obligation_result","obligation_index":3,"status":"items","reason_code":null,"items":[{"text":"我们其实是从做阳极板起家的。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
