{"record_type":"obligation_result","obligation_index":5,"status":"items","reason_code":null,"items":[{"text":"我们就是做这个起家的。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":6,"status":"items","reason_code":null,"items":[{"text":"后来发现装备我们也能做，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":7,"status":"no_supported_item","reason_code":"incomplete_phrase","items":[]}
{"record_type":"obligation_result","obligation_index":8,"status":"items","reason_code":null,"items":[{"text":"我们全流程攻克，从海绵钛到阴极辊成型，都由我们一手掌控，从材料原始状态加工成最终装备。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":9,"status":"items","reason_code":null,"items":[{"text":"意思是我们做得好是因为我们对材料本身比较懂？","semantic_type":"unknown","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":10,"status":"items","reason_code":null,"items":[{"text":"我们一开始就研究材料，从材料本身出发去设计装备。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":11,"status":"items","reason_code":null,"items":[{"text":"包括阳极槽的钛材，也是我们自己研发开发的材料，然后做成装备。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
